function uniqueSorted(values) {
  const seen = new Set();
  const result = [];
  for (const v of values) {
    if (typeof v === 'number' && Number.isFinite(v)) {
      if (!seen.has(v)) {
        seen.add(v);
        result.push(v);
      }
    }
  }
  return result.sort((a, b) => a - b);
}

